// Read-only host comparison of saved original F32/BF16 surfaces.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

struct Surface {
    std::vector<unsigned char> data;
    size_t size;
    Surface(const char *path,const char *kind):size(std::string(kind)=="f32"?4:2) {
        if(std::string(kind)!="f32" && std::string(kind)!="bf16") throw std::runtime_error("dtype");
        std::ifstream f(path,std::ios::binary|std::ios::ate);
        if(!f || f.tellg()<0) throw std::runtime_error("open");
        data.resize(size_t(f.tellg()));f.seekg(0);
        if(data.size()%size || !f.read(reinterpret_cast<char*>(data.data()),data.size())) throw std::runtime_error("extent");
    }
    uint32_t bits(size_t index)const {
        if(index>=data.size()/size)throw std::runtime_error("index");
        uint32_t out=0;std::memcpy(&out,data.data()+index*size,size);
        return size==2?out<<16u:out;
    }
};
float value(uint32_t bits){float f;std::memcpy(&f,&bits,4);return f;}
unsigned bf16(uint32_t bits){return ((bits+32767u+((bits>>16u)&1u))>>16u)&65535u;}
struct Stats {
    uint64_t cells=0,wrong_bits=0,wrong_bf16=0,nonfinite=0,rows_differ=0;
    double maximum=0,square_error=0,square_reference=0;
};
struct Sample{size_t row,column;uint32_t actual,reference;};
void add(Stats &s,uint32_t a,uint32_t b){
    ++s.cells;s.wrong_bits+=a!=b;s.wrong_bf16+=bf16(a)!=bf16(b);
    const double av=value(a),bv=value(b);
    if(!std::isfinite(av)||!std::isfinite(bv)){++s.nonfinite;return;}
    const double delta=av-bv;s.maximum=std::max(s.maximum,std::fabs(delta));
    s.square_error+=delta*delta;s.square_reference+=bv*bv;
}
void emit(const Stats&s){
    std::cout<<"{\"elements\":"<<s.cells<<",\"f32_bit_mismatches\":"<<s.wrong_bits
        <<",\"bf16_mismatches\":"<<s.wrong_bf16<<",\"nonfinite\":"<<s.nonfinite
        <<",\"bf16_rows_differ\":"<<s.rows_differ<<",\"maximum_absolute_error\":"<<s.maximum
        <<",\"relative_l2\":";
    if(s.square_reference>0)std::cout<<std::sqrt(s.square_error/s.square_reference);
    else if(s.square_error==0)std::cout<<0;else std::cout<<"null";
    std::cout<<"}";
}
int main(int argc,char**argv){try{
    if(argc!=11)throw std::runtime_error("arguments");
    Surface a(argv[1],argv[2]),b(argv[3],argv[4]);
    const size_t rows=std::stoull(argv[5]),cols=std::stoull(argv[6]),
      as=std::stoull(argv[7]),ao=std::stoull(argv[8]),bs=std::stoull(argv[9]),bo=std::stoull(argv[10]);
    if(!rows||!cols||ao+cols>as||bo+cols>bs||rows>8192||cols>524288||
       rows*as>a.data.size()/a.size||rows*bs>b.data.size()/b.size)throw std::runtime_error("shape");
    Stats total;std::vector<Stats> chunks((rows+63)/64);std::vector<Sample> samples;
    for(size_t row=0;row<rows;++row){
        bool different=false;
        for(size_t col=0;col<cols;++col){
            auto av=a.bits(row*as+ao+col),bv=b.bits(row*bs+bo+col);
            add(total,av,bv);add(chunks[row/64],av,bv);
            if(bf16(av)!=bf16(bv))different=true;
            if(av!=bv && samples.size()<16)samples.push_back({row,col,av,bv});
        }
        total.rows_differ+=different;chunks[row/64].rows_differ+=different;
    }
    std::cout<<std::setprecision(17)<<"{\"summary\":";emit(total);
    std::cout<<",\"chunks\":[";
    for(size_t i=0;i<chunks.size();++i){if(i)std::cout<<",";std::cout<<"{\"first_row\":"<<i*64<<",\"stats\":";emit(chunks[i]);std::cout<<"}";}
    std::cout<<"],\"first_differences\":[";
    for(size_t i=0;i<samples.size();++i){if(i)std::cout<<",";const auto&s=samples[i];
        std::cout<<"{\"row\":"<<s.row<<",\"column\":"<<s.column<<",\"actual_bits\":"<<s.actual
            <<",\"reference_bits\":"<<s.reference<<",\"actual\":";
        if(std::isfinite(value(s.actual)))std::cout<<value(s.actual);else std::cout<<"null";
        std::cout<<",\"reference\":";
        if(std::isfinite(value(s.reference)))std::cout<<value(s.reference);else std::cout<<"null";
        std::cout<<"}";
    }
    std::cout<<"]}\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}

