#include "native/providers/moe_accumulator/q1_moe_hawkeye_bf16_accumulator.h"
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
std::vector<uint16_t> load(const char* path,size_t count){
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if(!f || f.tellg()!=std::streamoff(count*2u))throw std::runtime_error("input extent");
    std::vector<uint16_t> data(count);f.seekg(0);
    if(!f.read(reinterpret_cast<char*>(data.data()),count*2u))throw std::runtime_error("input read");
    return data;
}
int main(int argc,char**argv){try{
    if(argc!=6)throw std::runtime_error("arguments");
    const unsigned rows=std::stoul(argv[3]),width=std::stoul(argv[4]);
    if(!rows||rows>8192||!width||width>4096||width%16u)throw std::runtime_error("shape");
    const auto w=load(argv[1],size_t(rows)*width),x=load(argv[2],width);
    if(std::filesystem::exists(argv[5]))throw std::runtime_error("output exists");
    std::vector<float> output(rows);
    for(unsigned row=0;row<rows;++row)
        output[row]=qrt_q1_moe_hawkeye::dot_bf16_hopper_blackwell(w.data()+size_t(row)*width,x.data(),width);
    std::ofstream file(argv[5],std::ios::binary|std::ios::out);
    file.write(reinterpret_cast<const char*>(output.data()),rows*4u);file.close();
    if(!file)throw std::runtime_error("output write");
    std::cout<<"{\"rows\":"<<rows<<",\"width\":"<<width<<",\"ascending_k16\":true,\"diagnostic_only\":true}\n";
    return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}

