#include "native/providers/gdn/sm121_q1_math.h"
#include <array>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace qrt_sm121_q1;
template<class T>std::vector<T> read(const char *path){
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if(!f||f.tellg()<0||size_t(f.tellg())>(18u<<20)||size_t(f.tellg())%sizeof(T))throw std::runtime_error("input extent");
    std::vector<T> x(size_t(f.tellg())/sizeof(T));f.seekg(0);
    if(!f.read(reinterpret_cast<char*>(x.data()),x.size()*sizeof(T)))throw std::runtime_error("input read");
    return x;
}
template<class T>void write(const std::string&path,const std::vector<T>&x){
    if(std::filesystem::exists(path))throw std::runtime_error("output exists");
    std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<const char*>(x.data()),x.size()*sizeof(T));f.close();
    if(!f)throw std::runtime_error("output write");
}
float residual_sumsq(const std::vector<float>&x){
    std::array<float,256> partial;
    for(unsigned lane=0;lane<256;++lane){const float*v=x.data()+lane*8;
        float sum=std::fma(v[0],v[0],multiply(v[1],v[1]));
        sum=std::fma(v[2],v[2],sum);sum=add(multiply(v[3],v[3]),sum);
        sum=std::fma(v[4],v[4],sum);sum=add(multiply(v[5],v[5]),sum);
        sum=std::fma(v[6],v[6],sum);partial[lane]=add(multiply(v[7],v[7]),sum);
    }
    for(unsigned step=16;step;step/=2)for(unsigned w=0;w<8;++w)for(unsigned lane=0;lane<step;++lane)
        partial[w*32+lane]=add(partial[w*32+lane],partial[w*32+lane+step]);
    std::array<float,8> warp;for(unsigned w=0;w<8;++w)warp[w]=partial[w*32];
    for(unsigned step=4;step;step/=2)for(unsigned w=0;w<step;++w)warp[w]=add(warp[w],warp[w+step]);
    return warp[0];
}
int main(int argc,char**argv){try{
    if(argc!=8)throw std::runtime_error("mode input-f32 other-f32 weight-bf16 rsqrt silu output-prefix");
    const std::string mode(argv[1]),output(argv[7]);
    const auto a=read<float>(argv[2]),b=read<float>(argv[3]);const auto w=read<uint16_t>(argv[4]);
    const auto table=read<unsigned char>(argv[5]);
    if(!qrt_sm121_rsqrt::valid_layout(table.data(),table.size()))throw std::runtime_error("rsqrt layout");
    std::vector<uint16_t> result(a.size()),residual;std::vector<float> inverse;
    if(mode=="gated"){
        const auto silu=read<float>(argv[6]);
        if(a.size()!=4096||b.size()!=4096||w.size()!=128||silu.size()!=65536)throw std::runtime_error("gated shape");
        inverse.resize(32);
        for(unsigned head=0;head<32;++head){std::array<float,16> partial;
            for(unsigned lane=0;lane<16;++lane){const float*x=a.data()+head*128+lane*8;
                float sum=std::fma(x[0],x[0],multiply(x[1],x[1]));
                for(unsigned j=2;j<8;++j)sum=std::fma(x[j],x[j],sum);
                partial[lane]=sum;
            }
            for(unsigned step=8;step;step/=2)for(unsigned lane=0;lane<step;++lane)partial[lane]=add(partial[lane],partial[lane+step]);
            const float inv=qrt_sm121_rsqrt::evaluate(table.data(),add(multiply(partial[0],1.f/128.f),1.e-6f));inverse[head]=inv;
            for(unsigned j=0;j<128;++j){const unsigned i=head*128+j;
                result[i]=bf16(multiply(multiply(multiply(a[i],inv),widen(w[j])),silu[bf16(b[i])]));}
        }
    }else if(mode=="consumer"){
        if(a.size()!=2048||b.size()!=2048||w.size()!=2048)throw std::runtime_error("consumer shape");
        std::vector<float> unrounded(2048);residual.resize(2048);inverse.resize(1);
        for(unsigned i=0;i<2048;++i){unrounded[i]=add(widen(bf16(a[i])),widen(bf16(b[i])));residual[i]=bf16(unrounded[i]);}
        const float inv=qrt_sm121_rsqrt::evaluate(table.data(),add(multiply(residual_sumsq(unrounded),1.f/2048.f),1.e-6f));inverse[0]=inv;
        for(unsigned i=0;i<2048;++i)result[i]=bf16(multiply(multiply(widen(residual[i]),inv),add(1.f,widen(w[i]))));
        write(output+"-residual-bf16.bin",residual);
    }else throw std::runtime_error("mode");
    write(output+"-norm-bf16.bin",result);write(output+"-inverse-f32.bin",inverse);
    std::cout<<"{\"mode\":\""<<mode<<"\",\"elements\":"<<a.size()<<",\"diagnostic_only\":true}\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
